mapper.update:
UPDATE sensor_config SET status='approved', approved_by=#{approvedBy}, reviewed_by=#{approvedBy},
    reviewed_at=UTC_TIMESTAMP(3), decision_reason=#{reason}, updated_at=UTC_TIMESTAMP(3)
WHERE id=#{configId} AND status='pending' AND requested_by IS NOT NULL AND requested_by <> #{approvedBy}

UPDATE sensor_config SET status='rejected', reviewed_by=#{reviewedBy}, reviewed_at=UTC_TIMESTAMP(3),
    decision_reason=#{reason}, updated_at=UTC_TIMESTAMP(3)
WHERE id=#{configId} AND status='pending' AND requested_by IS NOT NULL AND requested_by <> #{reviewedBy}
